describe('Mobile Navigation Collapse - Hamburger Menu', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should display hamburger menu on mobile viewport and toggle navigation links when clicked', () => {
    // Set viewport to mobile
    cy.viewport('iphone-x');

    // Verify hamburger menu button is visible
    cy.get('[data-testid="hamburger-menu-btn"]').should('be.visible');
    cy.get('[data-testid="hamburger-menu-btn"]').should('contain', 'Menu');

    // Verify navigation links are collapsed
    cy.get('[data-testid="nav-link-home"]').should('not.exist');
    cy.get('[data-testid="nav-link-about"]').should('not.exist');
    cy.get('[data-testid="nav-link-services"]').should('not.exist');
    cy.get('[data-testid="nav-link-contact"]').should('not.exist');

    // Click hamburger menu button
    cy.get('[data-testid="hamburger-menu-btn"]').click();

    // Verify navigation links are now visible
    cy.get('[data-testid="nav-link-home"]').should('be.visible');
    cy.get('[data-testid="nav-link-about"]').should('be.visible');
    cy.get('[data-testid="nav-link-services"]').should('be.visible');
    cy.get('[data-testid="nav-link-contact"]').should('be.visible');

    // Verify navigation links are clickable
    cy.get('[data-testid="nav-link-home"]').click();
    cy.url().should('include', '/');

    // Verify hamburger menu button is hidden
    cy.get('[data-testid="hamburger-menu-btn"]').should('not.exist');
  });

  it('should handle edge case when hamburger menu is clicked multiple times', () => {
    // Set viewport to mobile
    cy.viewport('iphone-x');

    // Verify hamburger menu button is visible
    cy.get('[data-testid="hamburger-menu-btn"]').should('be.visible');

    // Click hamburger menu button twice
    cy.get('[data-testid="hamburger-menu-btn"]').click();
    cy.get('[data-testid="hamburger-menu-btn"]').click();

    // Verify navigation links are still visible after multiple clicks
    cy.get('[data-testid="nav-link-home"]').should('be.visible');
    cy.get('[data-testid="nav-link-about"]').should('be.visible');
    cy.get('[data-testid="nav-link-services"]').should('be.visible');
    cy.get('[data-testid="nav-link-contact"]').should('be.visible');

    // Verify hamburger menu button is still hidden
    cy.get('[data-testid="hamburger-menu-btn"]').should('not.exist');
  });
});
